package com.steven.assets.service.srpp.settings;
import com.steven.assets.controller.*;import com.steven.assets.dto.SrppClaudeAuthDto;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class SrppClaudeAuthHttpTest {
 SrppClaudeAuthService service;MockMvc mvc;String base="/api/portfolio-advice/srpp/ai-auth/claude";
 @BeforeEach void setup(){service=mock(SrppClaudeAuthService.class);mvc=MockMvcBuilders.standaloneSetup(new SrppClaudeAuthController(service)).setControllerAdvice(new SrppClaudeAuthExceptionAdvice(),new GlobalExceptionHandler()).addFilters(new SrppClaudeAuthNoStoreFilter()).build();}
 @Test void missingBindingAndNativeErrorsUseSafeNoStoreAdvice()throws Exception{mvc.perform(get(base+"/state").param("toolId","claude")).andExpect(status().isBadRequest()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.code").value("AI_INVALID_REQUEST"));when(service.call(any(),any(),any(),any(),any())).thenThrow(new IllegalArgumentException("SECRET_NATIVE_CODE https://claude.com/private"));mvc.perform(post(base+"/complete").contentType("application/json").content("{}"));mvc.perform(get(base+"/state").param("toolId","claude").header("X-SRPP-AI-Auth-Binding","a".repeat(43))).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.message").value("登入作業無法完成，請重新確認登入狀態"));}
 @Test void stateContractAndNoStore()throws Exception{when(service.call(eq("state"),any(),eq("claude"),isNull(),isNull())).thenReturn(new SrppClaudeAuthDto.AuthLocalState(1,"claude","EXPIRED",java.time.Instant.parse("2000-01-01T00:00:00Z"),"AI_AUTH_EXPIRED"));mvc.perform(get(base+"/state").param("toolId","claude").header("X-SRPP-AI-Auth-Binding","a".repeat(43))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.loginState").value("EXPIRED")).andExpect(jsonPath("$.expiresAt").value("2000-01-01T00:00:00Z"));}
 @Test void earlyNoStoreCoversMissingQueryUnsupportedContentTypeAndMethod()throws Exception{mvc.perform(get(base+"/state").header("X-SRPP-AI-Auth-Binding","a".repeat(43))).andExpect(status().isBadRequest()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post(base+"/start").contentType("text/plain").content("private-code")).andExpect(header().string("Cache-Control","no-store"));mvc.perform(delete(base+"/state")).andExpect(header().string("Cache-Control","no-store"));}
}
